<?php namespace App\Services; use App\Repositories\{ClienteRepository,LancamentoRepository,PagamentoRepository}; class ClienteService { public function __construct(private ClienteRepository $clientes,private LancamentoRepository $lancamentos,private PagamentoRepository $pagamentos,private ScoreClienteService $score) {} public function owned(string $id):?array { $c=$this->clientes->find($id); return $c && $c['loja_id']===session('loja_id')?$c:null; } public function balance(string $id):float { return (float)(collect($this->lancamentos->where('cliente_id',$id))->where('status','!=','cancelado')->sum('valor')-collect($this->pagamentos->where('cliente_id',$id))->sum('valor')); } public function detail(array $c):array {$l=$this->lancamentos->where('cliente_id',$c['id']);$p=$this->pagamentos->where('cliente_id',$c['id']);[$color,$text]=$this->score->score($c,$l,$p);return compact('c','l','p','color','text')+['saldo'=>$this->balance($c['id'])];} }
